CREATE TABLE gomoku_games (id TEXT PRIMARY KEY, room TEXT NOT NULL REFERENCES rooms(code), n INTEGER NOT NULL, black_host INTEGER NOT NULL, ready_a INTEGER NOT NULL DEFAULT 0, ready_b INTEGER NOT NULL DEFAULT 0, board TEXT NOT NULL, turn INTEGER NOT NULL DEFAULT 1, winner TEXT, version INTEGER NOT NULL DEFAULT 0, winning TEXT, UNIQUE(room,n));
